/** Public catalog declarations. A profile describes a route within one credential origin. */
export interface PublicProviderModelDefaults {
  readonly name?: string;
  readonly contextWindow?: number;
  readonly maxOutputTokens?: number;
  readonly supportsImageInput?: boolean;
  readonly supportsFastMode?: boolean;
  readonly supportsToolCalls?: boolean;
  readonly efforts?: readonly string[];
  readonly defaultEffort?: string | null;
  readonly defaultEnabled?: boolean;
  readonly mode?: string;
  readonly modalities?: { readonly input?: readonly string[]; readonly output?: readonly string[] };
}

export interface PublicProviderInterface {
  readonly id: string;
  readonly providerId: string;
  readonly api: string;
  readonly baseUrl: string;
  readonly inputBaseUrls: readonly string[];
  readonly defaultFor?: readonly string[];
  readonly legacyApis?: readonly string[];
  readonly modelIds?: readonly string[];
  readonly compatibility?: readonly string[];
  readonly defaults?: PublicProviderModelDefaults;
}

interface PublicModelRoute {
  readonly providerId: string;
  readonly modelId: string;
  readonly variant?: "1m";
  readonly status?: string;
  readonly agents: readonly string[];
  readonly nativeApi?: string | null;
  readonly baseDefaults: PublicProviderModelDefaults;
  readonly defaults: PublicProviderModelDefaults;
  readonly perBackend?: Readonly<Record<string, PublicProviderModelDefaults>>;
  readonly interfaces?: readonly { readonly profileId: string }[];
  readonly preferredInterfaces?: Readonly<Record<string, readonly string[]>>;
}

interface CatalogRecommendation {
  readonly providerId: string;
  readonly modelId?: string;
  readonly modelIdPrefix?: string;
  readonly agent: string;
}

interface NativeApiRule {
  readonly providerId: string;
  readonly modelIdPrefix: string;
  readonly nativeApi: string;
}

const normalizedEndpoint = (value: string): string => value.replace(/\/+$/u, "");

function profileAcceptsEndpoint(profile: PublicProviderInterface, endpoint: string): boolean {
  const address = normalizedEndpoint(endpoint);
  return [profile.baseUrl, ...profile.inputBaseUrls].some(candidate => normalizedEndpoint(candidate) === address);
}

/** Established connections can offer catalog routes only when their endpoint identifies one product. */
export function publicProviderCatalogId(endpoint: string): string | undefined {
  const ids = [...new Set(providerInterfaceProfiles.filter(profile => profileAcceptsEndpoint(profile, endpoint)).map(profile => profile.providerId))];
  if (ids.length !== 0) return ids.length === 1 ? ids[0] : undefined;
  switch (normalizedEndpoint(endpoint)) {
    case "https://api.openai.com/v1": return "openai";
    case "https://api.anthropic.com": return "anthropic";
    default: return undefined;
  }
}

function providerModelId(providerId: string, modelId: string): string {
  const bare = modelId.replace(/\[1m\]$/u, "");
  if (providerId === "openai") return bare.replace(/^chatgpt\//u, "");
  return providerId === "xai" && !bare.startsWith("xai/") ? "xai/" + bare : bare;
}

export function publicProviderModel(providerId: string, modelId: string): PublicModelRoute | undefined {
  const models = matchingPublicModels(providerId, modelId);
  return models.length === 1 ? models[0] : undefined;
}

function matchingPublicModels(providerId: string, modelId: string): readonly PublicModelRoute[] {
  const id = providerModelId(providerId, modelId);
  const models = publicModelRoutes.filter(model => model.providerId === providerId && model.modelId === id);
  const explicit = modelId.endsWith("[1m]") ? models.filter(model => model.variant === "1m") : [];
  return explicit.length > 0 ? explicit : models.filter(model => model.variant === undefined);
}

export function publicModelNativeApi(providerId: string, modelId: string, mode?: string): string | null | undefined {
  const models = matchingPublicModels(providerId, modelId);
  if (models.some(model => model.status === "retired" || model.nativeApi === null)) return null;
  const declared = [...new Set(models.flatMap(model => model.nativeApi ? [model.nativeApi] : []))];
  if (declared.length > 0) return declared.length === 1 ? declared[0] : null;
  const model = models[0];
  const effectiveMode = mode ?? model?.defaults.mode ?? model?.baseDefaults.mode;
  if (effectiveMode !== undefined && effectiveMode !== "chat" && effectiveMode !== "responses") return undefined;
  const id = providerModelId(providerId, modelId);
  return nativeApiRules.find(rule => rule.providerId === providerId && id.startsWith(rule.modelIdPrefix)
    && !id.slice(rule.modelIdPrefix.length).includes("/"))?.nativeApi;
}

export function publicModelRecommendedBackend(providerId: string, modelId: string): string | undefined {
  const id = providerModelId(providerId, modelId);
  const rules = recommendedAgents.filter(rule => rule.providerId === providerId);
  return (rules.find(rule => rule.modelId === id)
    ?? rules.filter(rule => rule.modelIdPrefix !== undefined && id.startsWith(rule.modelIdPrefix))
      .sort((a, b) => b.modelIdPrefix!.length - a.modelIdPrefix!.length)[0])?.agent;
}

export function publicProviderInterfaces(providerId: string, endpoint: string, modelId?: string): readonly PublicProviderInterface[] {
  const models = modelId === undefined ? [] : matchingPublicModels(providerId, modelId);
  const declaration = models[0];
  if (models.length > 1 || declaration?.status === "retired") return [];
  return providerInterfaceProfiles.filter(profile => profile.providerId === providerId && profileAcceptsEndpoint(profile, endpoint)
    && (declaration?.interfaces !== undefined ? declaration.interfaces.some(binding => binding.profileId === profile.id)
      : profile.modelIds === undefined || modelId !== undefined && profile.modelIds.includes(modelId)));
}

export function isPreferredPublicProviderInterface(profile: PublicProviderInterface, endpoint: string, backendId: string, modelId?: string): boolean {
  const order = modelId === undefined ? undefined : publicProviderModel(profile.providerId, modelId)?.preferredInterfaces?.[backendId];
  if (order !== undefined) return order.includes(profile.id);
  if (profile.providerId === "zhipu-glm-cn" && backendId === "pi") return normalizedEndpoint(profile.baseUrl) === normalizedEndpoint(endpoint);
  return profile.defaultFor?.includes(backendId) === true;
}

export function preferredPublicProviderInterface(profiles: readonly PublicProviderInterface[], endpoint: string, backendId: string, modelId?: string): PublicProviderInterface | undefined {
  const providerId = profiles[0]?.providerId;
  const model = providerId === undefined || modelId === undefined ? undefined : publicProviderModel(providerId, modelId);
  const order = model?.preferredInterfaces?.[backendId];
  if (order !== undefined) {
    for (const id of order) {
      const profile = profiles.find(candidate => candidate.id === id);
      if (profile !== undefined) return profile;
    }
  }
  return profiles.find(profile => isPreferredPublicProviderInterface(profile, endpoint, backendId, modelId))
    ?? (model?.interfaces !== undefined ? profiles[0] : undefined);
}

